const items = $input.all();

const newsletterDate = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const articles = items.filter(i => !i.json._batchError && i.json.headline);

if (articles.length === 0) {
  return [{
    json: {
      newsletter_html: '<p>No new articles today.</p>',
      newsletter_date: newsletterDate,
      article_count: 0
    }
  }];
}

const streams = {};

for (const item of articles) {
  const a = item.json;
  const s = a.stream || 'General';

  if (!streams[s]) streams[s] = [];
  streams[s].push(a);
}

const streamOrder = [
  'Insurance News',
  'Claims News',
  'Opinions',
  'Legal Commentary',
  'Catastrophe / Disaster'
];

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildRow(a) {
  const d = a.date
    ? new Date(a.date).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric'
      })
    : '';

  const headline = escapeHtml(a.headline || '');
  const summary = escapeHtml(a.summary || '');
  const whyItMatters = escapeHtml(a.why_it_matters || '');
  const source = escapeHtml(a.source || '');
  const sourceUrl = a.source_url || '#';

  return `
    <tr>
      <td style="padding:0 24px 18px 24px;">
        <table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
          <tr>
            <td style="padding:22px 22px 20px 22px;border-left:4px solid #004080;">

              <table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">
                <tr>
                  <td style="padding:0 0 8px 0;">
                    <h3 style="margin:0;font-size:17px;line-height:1.35;font-weight:700;color:#1a1a2e;">
                      <a href="${sourceUrl}" style="color:#1a1a2e;text-decoration:none;">
                        ${headline}
                      </a>
                    </h3>
                  </td>
                </tr>
              </table>

              <p style="margin:0 0 14px 0;font-size:14px;color:#374151;line-height:1.65;">
                ${summary}
              </p>

              <table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;margin:0 0 14px 0;">
                <tr>
                  <td style="background:#ecfdf5;border:1px solid #d1fae5;border-radius:8px;padding:12px 14px;">
                    <p style="margin:0;font-size:13px;color:#065f46;line-height:1.55;">
                      <strong style="color:#059669;">Why it matters:</strong> ${whyItMatters}
                    </p>
                  </td>
                </tr>
              </table>

              <table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">
                <tr>
                  <td align="left" style="vertical-align:middle;">
                    <a href="${sourceUrl}" style="display:inline-block;background:#004080;color:#ffffff;text-decoration:none;font-size:12px;font-weight:700;letter-spacing:.2px;padding:9px 13px;border-radius:999px;">
                      Read full article
                    </a>
                  </td>
                  <td align="right" style="vertical-align:middle;font-size:12px;color:#6b7280;line-height:1.4;">
                    ${source}${d ? ' &bull; ' + d : ''}
                  </td>
                </tr>
              </table>

            </td>
          </tr>
        </table>
      </td>
    </tr>
  `;
}

function buildSection(key, arts) {
  return `
    <tr>
      <td style="padding:28px 24px 14px 24px;">
        <table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-collapse:collapse;">
          <tr>
            <td style="background:#004080;border-radius:10px;padding:13px 16px;">
              <h2 style="margin:0;font-size:16px;line-height:1.3;font-weight:700;color:#ffffff;">
                ${escapeHtml(key)}
              </h2>
            </td>
            <td width="72" align="right" style="background:#004080;border-radius:10px;padding:13px 16px;font-size:12px;color:#bfdbfe;font-weight:700;">
              ${arts.length} ${arts.length === 1 ? 'item' : 'items'}
            </td>
          </tr>
        </table>
      </td>
    </tr>
    ${arts.map(buildRow).join('')}
  `;
}

let body = '';
const used = {};

for (const k of streamOrder) {
  if (streams[k]) {
    body += buildSection(k, streams[k]);
    used[k] = true;
  }
}

for (const k of Object.keys(streams)) {
  if (!used[k]) {
    body += buildSection(k, streams[k]);
  }
}

