}
return results.length > 0 ? results : [{ json: { _empty: true, source: 'Google News' } }];

// Build a Set of url_hashes from the SharePoint cache for fast lookup
const items = $input.all();
const seenHashes = new Set();
for (const item of items) {
  const j = item.json || {};
  const h = j.url_hash || j.URL_HASH || j['url_hash'];
  if (h && typeof h === 'string') seenHashes.add(h.trim());
}
console.log('Loaded ' + seenHashes.size + ' previously seen article hashes');
return [{ json: { seenHashes: Array.from(seenHashes), seenCount: seenHashes.size } }];

function simpleHash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(36) + '_' + s.length.toString(36);
}

const raw = $input.first().json;
const arr = raw.results || [];
const results = [];

for (const op of arr) {
  // v4 Search API field names
  const link = op.absolute_url ? 'https://www.courtlistener.com' + op.absolute_url : '';
  const title = op.caseName || op.caseNameFull || 'Untitled Opinion';
  if (!link || !title) continue;

  let date = '';
  if (op.dateFiled) date = new Date(op.dateFiled).toISOString();
  else if (op.dateArgued) date = new Date(op.dateArgued).toISOString();

  // Use the snippet field (v4 search returns snippets, not full text)
  let description = '';
  if (Array.isArray(op.opinions) && op.opinions[0] && op.opinions[0].snippet) {
    description = op.opinions[0].snippet.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().substring(0, 400);
  }

  // Court display name and ID
  const court = op.court || '';
  const courtId = op.court_id || '';
  const docket = op.docketNumber || '';
  const citations = Array.isArray(op.citation) ? op.citation.join(', ') : '';

  const cleanLink = link.toLowerCase().replace(/\/$/, '').split('?')[0];

  results.push({
    json: {
      title: title.trim(),
      date,
      link: link.trim(),
      url_hash: simpleHash(cleanLink),
      source: 'CourtListener',
      stream: 'Opinions',
      court,
      court_id: courtId,
      docket,
      citations,
      description
    }
  });
}

return results.length > 0 ? results : [{ json: { _empty: true, source: 'CourtListener' } }];

// Filter merged articles to only those NOT in the seen-hash set
const items = $input.all();
const seenArr = $('Build Seen Hash Set').first().json.seenHashes || [];
const seenSet = new Set(seenArr);
const seenLinkSet = new Set();
const kept = [];
let alreadySeen = 0, duplicateInRun = 0, empty = 0;
for (const item of items) {
  const j = item.json;
  if (j._empty || !j.title || !j.link || !j.url_hash) { empty++; continue; }
  if (seenSet.has(j.url_hash)) { alreadySeen++; continue; }
  if (seenLinkSet.has(j.url_hash)) { duplicateInRun++; continue; }
  seenLinkSet.add(j.url_hash);
  kept.push(item);
}
console.log('New=' + kept.length + ', alreadySeen=' + alreadySeen + ', duplicateInRun=' + duplicateInRun + ', empty=' + empty);
if (kept.length === 0) return [{ json: { _noItems: true, message: 'No new articles to summarize.' } }];
return kept;

// Collect all url_hashes from articles that were summarized and sent
const filtered = $('Filter Unseen Articles').all();
const today = new Date().toISOString().split('T')[0];
const rows = [];
for (const item of filtered) {
  const j = item.json;
  if (!j.url_hash || j._noItems) continue;
  rows.push({ json: { url_hash: j.url_hash, seen_date: today, source: j.source || 'Unknown' } });
}
console.log('Appending ' + rows.length + ' new hashes to seen cache');
return rows.length > 0 ? rows : [{ json: { _empty: true } }];

const items = $input.all();
const floridaKeywords = /\b(florida|fla\.|miami|tampa|orlando|jacksonville|tallahassee|fort lauderdale|hurricane|dca|sinkhole)\b/i;
const insuranceKeywords = /\b(insur|claim|policy|premium|adjuster|coverage|deductible|liability|carrier|reinsur|catastrophe|cat loss|underwrit|appraisal|bad faith|liti|appeal|opinion)\b/i;

const kept = [];
let dropped = 0;
for (const item of items) {
  const j = item.json;
  if (j._noItems) { kept.push(item); continue; }
  const text = ((j.title || '') + ' ' + (j.description || '')).toLowerCase();

  // CourtListener and Property Insurance Blog get a free pass — they're already relevant by nature
  if (j.source === 'CourtListener' || j.source === 'Property Insurance Coverage Law Blog') {
    kept.push(item);
    continue;
  }

  // For broader sources, require BOTH a Florida signal AND an insurance/legal signal
  const isFL = floridaKeywords.test(text);
  const isInsLegal = insuranceKeywords.test(text);

  if (isFL && isInsLegal) {
    kept.push(item);
  } else {
    dropped++;
  }
}
console.log('Relevance filter: kept=' + kept.length + ', dropped=' + dropped);
return kept.length > 0 ? kept : [{ json: { _noItems: true, message: 'No relevant articles after filter.' } }];

